// One switch: accept cash at the end of the trip for this vehicle service (Payments contract 03P, D4).
function CashSwitch({vehicle,service,saved,onSaved}){
  const [state,setState]=useState('idle'),[message,setMessage]=useState('')
  const ready=saved&&saved.version>0,on=Boolean(saved?.cash_accepted)
  async function change(next){
    setState('saving');setMessage('')
    try{
      const result=await api(`/vehicles/${vehicle}/services/${service}/payment-options`,{method:'PATCH',body:JSON.stringify({expected_version:saved.version,cash_accepted:next})})
      onSaved({...saved,version:result.version,cash_accepted:result.cash_accepted});setState('saved')
    }catch(error){
      setState('error');const code=error.code
      if(code==='VERSION_CONFLICT'){setMessage(t('These rates changed in another window. They were reloaded, so try the switch again.'));api(`/vehicles/${vehicle}/services`).then(r=>{const row=(r.items||[]).find(x=>x.service_type_id===service);if(row)onSaved(row)}).catch(()=>{})}
      else if(code==='VEHICLE_SERVICE_NOT_FOUND')setMessage(t('Save the rates for this service first, then turn cash on.'))
      else if(code==='VEHICLE_NOT_FOUND'||error.status===404)setMessage(t('We could not find this vehicle. Go back and choose it again.'))
      else if(code==='CASH_NOT_ALLOWED')setMessage(t('Cash is not available for ticket services. They are paid online only.'))
      else setMessage(error.message||t('The change could not be saved. Please try again.'))
    }
  }
  return <div className="tk-cash-row"><label className="ui-switch"><input type="checkbox" role="switch" checked={on} disabled={!ready||state==='saving'} onChange={e=>change(e.target.checked)}/><span className="ui-switch-track" aria-hidden="true"/><span>{t('Accept cash at the end of the trip')}</span></label>
    <span className="tk-cash-status" role="status" aria-live="polite">{state==='saving'?t('Saving…'):state==='saved'?t('Saved'):!ready?t('Save the rates first, then you can turn this on.'):''}{state==='error'&&<span className="is-error">{message}</span>}</span>
    <InfoTip>{t('Passengers can then choose to pay you in cash after the trip. The Driver and the Passenger both confirm, and Travelly commission is still due.')}</InfoTip></div>
}
// Event hire has packages, not route rates (03EV): its status comes from GET /owners/me/service-readiness and the packages are set in the vehicle's Event packages tab.
function EventStatus({ vehicle, readiness }) {
  const entry = ((readiness.find(v => v.vehicle_id === vehicle) || {}).services || []).find(s => s.pricing_scope === 'EVENT')
  if (!entry) return null
  return <div className="tk-bar"><Chip tone={entry.ready ? 'success' : 'info'}>{t('Event hire')}: {entry.ready ? t('Ready') : t('Not ready')}</Chip><Chip tone="muted">{t(entry.rate_rule_count === 1 ? '{value0} package' : '{value0} packages', { value0: entry.rate_rule_count })}</Chip><Link className="ui-button ui-button-secondary" to={`/owner/vehicles/${encodeURIComponent(vehicle)}?tab=event-packages`}>{t('Set up Event packages')}</Link></div>
}

export default function OwnerRates() {
  const location = useLocation(), defaults = new URLSearchParams(location.search)
  const [user, setUser] = useState(null), [vehicles, setVehicles] = useState([]), [services, setServices] = useState([]), [vehicle, setVehicle] = useState(()=>defaults.get('vehicle')||''), [service, setService] = useState(()=>defaults.get('service')||''), [saved, setSaved] = useState(null), [error, setError] = useState(null), [readiness, setReadiness] = useState([])
  useEffect(() => { if (!hasSession()) return; let active = true; Promise.all([api('/users/me'), api('/owners/me/vehicles'), api('/service-types'), api('/owners/me/service-readiness').catch(() => ({ items: [] }))]).then(([u, v, s, r]) => { if (active) { setUser(u); setVehicles(v.items); setServices(s.items.filter(x => x.pricing_scope !== 'EVENT')); setReadiness(r.items || []) } }).catch(err => { if (active) setError(err) }); return () => { active = false } }, [])
  useEffect(() => { setSaved(null); if (!vehicle || !service) return; let active = true; api(`/vehicles/${vehicle}/services`).then(result => { if (active) setSaved(result.items.find(r => r.service_type_id === service) || { version: 0, rules: [] }) }).catch(err => { if (active) setError(err) }); return () => { active = false } }, [vehicle, service])
  const w = useWizard(RATE_STEPS.length + 1), rw = { ...w, step: w.step - 1, count: RATE_STEPS.length, min: -1 }
  if (!hasSession()) return <Navigate to="/login" replace/>
  if (user && !user.approved_roles.includes('OWNER')) return <Navigate to="/" replace/>
  return <><Header/><FlowShell heading={t("Reusable vehicle rates")} title={w.step === 0 ? 'Vehicle and service' : ['Rate basics', 'Pickup area and route', 'Rate', 'Waiting and return', 'Trip changes', 'Other costs', 'Example preview'][w.step - 1]} icon="wallet" steps={['Vehicle', ...RATE_STEPS]} current={w.step} onStepSelect={w.goTo}><Compact.Provider value={true}><ErrorNotice error={error}/>{w.step === 0 && <div className="flow-wizard-form"><div className="rate-vehicle-picker rate-grid"><Field label="Vehicle"><select required value={vehicle} onChange={e => { setVehicle(e.target.value); setError(null) }}><option value="">{t("Choose your vehicle")}</option>{vehicles.map(v => <option key={v.id} value={v.id}>{t(v.label)}</option>)}</select></Field><Field label="Private-hire service"><select required value={service} onChange={e => setService(e.target.value)}><option value="">{t("Choose the offered service")}</option>{services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field></div><p className="flow-note">{t("Configure Airport, Local, or Long-distance rates for journeys you cover. Each matching request receives a fresh quote; the selected rate-rule version and calculation are preserved when the Passenger accepts it.")}</p>{user && !vehicles.length && <p role="status">{t("You do not have a vehicle available for rate configuration yet. Vehicle registration and verification are separate from Owner approval.")}</p>}{user && !services.length && <p role="status">{t("No approved Airport, Local, or Long-distance service is configured yet. An Admin must classify and activate a service before these rates can be saved.")}</p>}{vehicle && <EventStatus vehicle={vehicle} readiness={readiness}/>}{vehicle && service && !saved && !error && <p role="status">{t("Loading saved rates…")}</p>}{vehicle && service && saved && <CashSwitch vehicle={vehicle} service={service} saved={saved} onSaved={setSaved}/>}<WizardNav w={w} onNext={() => { if (!vehicle || !service) { setError(new Error('Choose a vehicle and a service to continue.')); return } if (!saved) return; setError(null); w.forward() }}/></div>}{saved && <div className="rate-form-host flow-wizard-form" hidden={w.step === 0}><RateForm wizard={rw} key={`${vehicle}-${service}`} initial={saved} onSave={async rules => { const result = await api(`/vehicles/${vehicle}/services`, { method: 'PUT', body: JSON.stringify({ service_type_id: service, expected_version: saved.version, enabled: true, currency: 'LKR', rules }) }); setSaved(result); return result }} onPreview={(rule, example) => api(`/vehicles/${vehicle}/services/preview`, { method: 'POST', body: JSON.stringify({ rule, example }) })}/></div>}</Compact.Provider></FlowShell></>
}
